#!/usr/bin/env python3
"""Baut die Release-Notes aus den PRs, die seit dem vorherigen Release in main
gemergt wurden: pro PR Titel + Beschreibung (ohne Test-Plan und Signatur).

Aufruf: release_notes.py <owner/repo> <tag> [<vorheriger-tag>] [<seit-datum>]
  - Ohne vorherigen Tag werden alle PRs berücksichtigt; <seit-datum> (YYYY-MM-DD)
    begrenzt das, z.B. für das allererste Release.
  - Env NOTES_REF (Commit/SHA) bestimmt das Enddatum, solange der Tag noch
    nicht existiert; sonst gilt der Tag-Commit.
Benötigt die gh-CLI (GH_TOKEN) und schreibt die Notes nach stdout.
"""
import json
import os
import re
import subprocess
import sys


def gh(path):
    out = subprocess.run(["gh", "api", "--paginate", path], check=True, capture_output=True, text=True).stdout
    # --paginate hängt mehrere JSON-Arrays aneinander
    items, dec, i = [], json.JSONDecoder(), 0
    out = out.strip()
    while i < len(out):
        obj, j = dec.raw_decode(out, i)
        items.extend(obj if isinstance(obj, list) else [obj])
        i = j
        while i < len(out) and out[i] in " \n\r\t":
            i += 1
    return items


def commit_date(repo, ref):
    return gh(f"repos/{repo}/commits/{ref}")[0]["commit"]["committer"]["date"]


def clean_body(body, title=""):
    body = (body or "").replace("\r\n", "\n")
    # Test-Plan-/Verification-Abschnitt (bis zur nächsten ##-Überschrift) entfernen
    body = re.sub(r"(?ms)^#{2,3} (?:Test plan|Verification)\b.*?(?=^#{2,3} |\Z)", "", body)
    # Signatur-Zeilen und Session-Links entfernen
    body = re.sub(r"(?m)^🤖 Generated with.*$", "", body)
    body = re.sub(r"(?ms)^---\s*\n_Generated by .*?_\s*\Z", "", body.rstrip() + "\n")
    # Überschrift, die nur den PR-Titel wiederholt, entfernen
    body = re.sub(r"(?m)^#{1,3} " + re.escape(title) + r"\s*$\n?", "", body)
    body = re.sub(r"(?m)^.*claude\.ai/code/session_.*$", "", body)
    # Überschriften eine Ebene unter den PR-Titel setzen
    body = re.sub(r"(?m)^## Summary\s*$\n?", "", body)
    body = re.sub(r"(?m)^#{2,3} (.+)$", r"#### \1", body)
    return re.sub(r"\n{3,}", "\n\n", body).strip()


def main():
    repo, tag = sys.argv[1], sys.argv[2]
    prev = sys.argv[3] if len(sys.argv) > 3 and sys.argv[3] else ""
    until = commit_date(repo, os.environ.get("NOTES_REF") or tag)
    since = commit_date(repo, prev) if prev else (sys.argv[4] if len(sys.argv) > 4 else "")

    prs = [p for p in gh(f"repos/{repo}/pulls?state=closed&base=main&per_page=100")
           if p.get("merged_at") and p["merged_at"] <= until and (not since or p["merged_at"] > since)]
    prs.sort(key=lambda p: p["merged_at"])

    lines = [f"## What's new in {tag}", ""]
    if not prs:
        lines += ["No pull requests were merged since the previous release.", ""]
    for p in prs:
        lines += [f"### {p['title']} (#{p['number']})", ""]
        body = clean_body(p.get("body"), p["title"])
        if body:
            lines += [body, ""]
    if prev:
        lines += [f"**Full changelog:** https://github.com/{repo}/compare/{prev}...{tag}", ""]
    print("\n".join(lines).rstrip() + "\n")


if __name__ == "__main__":
    main()
